				lab.fleet.instances[id] = instance
			}
			lab.enrollment.pool = tc.pool
			if err := lab.setup(ctx, t.TempDir(), metadata, ip); err == nil {
				t.Fatal("pool node was admitted")
			}
		})
	}
}

