type renameHosts struct {
	mu       sync.Mutex
	nodes    []string
	down     map[string]bool
	sessions map[string]string
	desired  map[string]host.Desired
	retired  []string
}

func newRenameHosts() *renameHosts {
	h := &renameHosts{nodes: []string{"ctl-1", "ctl-2", "ctl-3"}, down: map[string]bool{},
		sessions: map[string]string{"ctl-1": "s1", "ctl-2": "s2", "ctl-3": "s3"}, desired: map[string]host.Desired{}}
	for _, node := range h.nodes {
		for _, role := range []string{"terrabase", "ts-auth"} {
			h.desired[node+"/"+role] = host.Desired{Node: node, Role: role, Generation: 15,
				Digest: strings.Repeat("a", 64), Env: map[string]string{"ROLE": role}}
		}
	}
	return h
}

func (h *renameHosts) enroll(from, to string) {
	h.mu.Lock()
	defer h.mu.Unlock()
	if !slices.Contains(h.nodes, to) {
		h.nodes = append(h.nodes, to)
	}
	h.down[from], h.sessions[to] = true, "n1"
}

func (h *renameHosts) ListHosts(context.Context) ([]host.HostStatus, error) {
	h.mu.Lock()
	defer h.mu.Unlock()
	var statuses []host.HostStatus
	for _, node := range h.nodes {
		status := host.HostStatus{Registration: host.Registration{Node: node, Roles: []string{"terrabase", "ts-auth"}}}
		if h.sessions[node] != "" && !h.down[node] {
			status.SessionExpiresAt = time.Now().Add(30 * time.Second)
		}
		for _, role := range status.Registration.Roles {
			if d, ok := h.desired[node+"/"+role]; ok && !d.Withdrawn && !h.down[node] {
				status.Reports = append(status.Reports, host.Report{Node: node, Role: role, Generation: d.Generation,
					State: "running", SessionID: h.sessions[node], ObservedAt: time.Now()})
			}
		}
		statuses = append(statuses, status)
	}
	return statuses, nil
}

func (h *renameHosts) ListDesired(_ context.Context, role string) ([]host.Desired, error) {
	h.mu.Lock()
	defer h.mu.Unlock()
	var desired []host.Desired
	for _, d := range h.desired {
		if role == "" || d.Role == role {
			desired = append(desired, d)
		}
	}
	return desired, nil
}

// ApplyDesired refuses what the host controller refuses: a withdrawal with
// execution data, and a generation that moves back or changes in place.
func (h *renameHosts) ApplyDesired(_ context.Context, d host.Desired) (host.Receipt, error) {
	h.mu.Lock()
	defer h.mu.Unlock()
	if d.Withdrawn && (d.Digest != "" || len(d.Args) != 0 || len(d.Env) != 0 || len(d.Secrets) != 0) {
		return host.Receipt{}, errors.New("withdrawn desired contains execution data")
	}
	if current, ok := h.desired[d.Node+"/"+d.Role]; ok && (d.Generation < current.Generation ||
		d.Generation == current.Generation && current.Withdrawn != d.Withdrawn) {
		return host.Receipt{}, errors.New("generation moved backward or changed within a generation")
	}
	h.desired[d.Node+"/"+d.Role] = d
	return host.Receipt{}, nil
}

func (h *renameHosts) RetireIdle(_ context.Context, node string) (bool, error) {
	h.mu.Lock()
	defer h.mu.Unlock()
	h.retired = append(h.retired, node)
	return true, nil
}

func (o *nodeOps) moveDesired(ctx context.Context, epoch uint64, from, to string) (bool, error) {
	statuses, err := o.fence.hosts.ListHosts(ctx)
	if err != nil {
		return false, err
	}
	if !slices.ContainsFunc(statuses, func(status host.HostStatus) bool {
		return status.Registration.Node == to && !status.SessionExpiresAt.IsZero()
	}) {
		return false, nil
	}
	desired, err := o.fence.hosts.ListDesired(ctx, "")
	if err != nil {
		return false, err
	}
	for _, d := range desired {
		if d.Node != from || d.Withdrawn {
			continue
		}
		// The workload reconciler may have placed the replica already.
		if !slices.ContainsFunc(desired, func(e host.Desired) bool { return e.Node == to && e.Role == d.Role && !e.Withdrawn }) {
			if err := o.carryPermit(ctx, epoch, d, from, to); err != nil {
				return false, err
			}
			moved := d
			moved.Node, moved.AuthorityEpoch = to, epoch
			if _, err := o.desired.ApplyDesired(ctx, moved); err != nil {
				return false, fmt.Errorf("move %s to %s: %w", d.Role, to, err)
			}
		}
		// A withdrawal carries no execution data and moves the generation on.
		withdrawn := host.Desired{Cell: d.Cell, Node: d.Node, Environment: d.Environment, Role: d.Role,
			Generation: d.Generation + 1, AuthorityEpoch: epoch, Withdrawn: true}
		if _, err := o.desired.ApplyDesired(ctx, withdrawn); err != nil {
			return false, fmt.Errorf("withdraw %s from %s: %w", d.Role, from, err)
		}
	}
	// ponytail: the old name's registration stays, retired; delete it once
	// a host plane API removes registrations.
	_, err = o.desired.RetireIdle(ctx, from)
	return err == nil, err
}

// carryPermit gives to the permit from holds for d's release: a release the
// fence sequences starts a host only on its node's permit, and the renamed
// node already ran this one.
func (o *nodeOps) carryPermit(ctx context.Context, epoch uint64, d host.Desired, from, to string) error {
	release := releaseOf(d.Generation)
	if _, err := o.fence.kv.Get(ctx, permitKey(d.Role, release, from)); errors.Is(err, jetstream.ErrKeyNotFound) {
		return nil
	} else if err != nil {
		return err
	}
	if err := o.fence.fencer.Guard(ctx, epoch); err != nil {
		return err
	}
	_, err := o.fence.kv.Put(ctx, permitKey(d.Role, release, to), []byte("{}"))
	return err
}

