// fakeNodePool is the cell's pool as OCI lists it.
type fakeNodePool struct{ state nodescale.PoolState }

func (pool fakeNodePool) Observe(context.Context) (nodescale.PoolState, error) {
	return pool.state, nil
}

func poolOf(members ...nodescale.PoolInstance) fakeNodePool {
	return fakeNodePool{state: nodescale.PoolState{Exists: true, Instances: members}}
}

// reconcile adopts a cell spec reconciling the tsauth role, as apply would.
func (lab staticEnrollmentLab) reconcile() {
	set := lab.enrollment.services.current
	set.Generation++
	set.Services = []cellspec.Service{{Role: tsauth.Role,
		Profile: cellspec.Profile{Resources: placement.Resources{CPU: 1, MemoryBytes: 1 << 30, DiskBytes: 2 << 30}},
		Spec:    &workload.ServiceSpec{Role: tsauth.Role}}}
	lab.enrollment.services.adopt(set, set.Generation)
}

// launchPoolNode records a node pool instance named node at ip, of the 2 OCPU,
// 12 GB shape the pool launches, and returns its host-setup metadata.
func (lab staticEnrollmentLab) launchPoolNode(t *testing.T, id, node, ip string) hostenroll.InstanceMetadata {
	t.Helper()
	descriptor := hostboot.Static("gru", "GRU", node)
	wire, err := descriptor.CanonicalBytes()
	if err != nil {
		t.Fatal(err)
	}
	ocpus, memory := float32(2), float32(12)
	lab.fleet.instances[id] = oci.CloudInstance{ID: id, DisplayName: node, PrivateIP: ip, FaultDomain: "FAULT-DOMAIN-1",
		LifecycleState: "RUNNING", Ocpus: &ocpus, MemoryInGBs: &memory,
		FreeformTags: map[string]string{"ts-cell": "gru", "ts-role": "node"}}
	return hostenroll.InstanceMetadata{InstanceID: id, Descriptor: descriptor, Wire: wire}
}

// staticHostFleet is the regional fleet as the static enrollment path sees
// it: only ObserveStaticHost is reachable.
type staticHostFleet struct {
	oci.Fleet
	instances map[string]oci.CloudInstance
	// observed, when set, runs before each static host observation.
	observed func()
}

func (fleet *staticHostFleet) ObserveStaticHost(_ context.Context, instanceID, node string) (oci.CloudInstance, error) {
	if fleet.observed != nil {
		fleet.observed()
	}
	instance, ok := fleet.instances[instanceID]
	if !ok || instance.FreeformTags["terrascale-host-node"] != node {
		return oci.CloudInstance{}, oci.ErrForeignResource
	}
	return instance, nil
}

// ObserveNamedHost returns the running instance named node, as the OCI
// observer does for a granted host.
func (fleet *staticHostFleet) ObserveNamedHost(_ context.Context, instanceID, node string) (oci.CloudInstance, error) {
	if fleet.observed != nil {
		fleet.observed()
	}
	instance, ok := fleet.instances[instanceID]
	if !ok || instance.DisplayName != node {
		return oci.CloudInstance{}, oci.ErrForeignResource
	}
	return instance, nil
}

type staticEnrollmentLab struct {
	enrollment *managedHostEnrollment
	controller *host.Controller
	fleet      *staticHostFleet
	bundle     hostenroll.PublicBundle
	epoch      uint64
	js         jetstream.JetStream
}

func startStaticEnrollmentLab(t *testing.T, ctx context.Context, workloads map[string]WorkloadProfile) staticEnrollmentLab {
	t.Helper()
	root := t.TempDir()
	broker, err := newAuthenticatedNATS(t, "gru").start(t, ctx, natscell.Config{
		Cell: "gru", Instance: "static-enrollment", Replicas: 1,
		Embedded: &natscell.Embedded{Host: "127.0.0.1", Port: -1, StoreDir: filepath.Join(root, "nats")},
	})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = broker.Close() })
	control, err := authority.Start(ctx, broker.JetStream(), authority.Config{DeploymentID: "01ARZ3NDEKTSV4RRFFQ69G5FAV", Scope: "gru", CandidateID: "0000000000F8TA328PVB21XWJY", Replicas: 1})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = control.Close() })
	if !control.Current().CanMutate() {
		t.Fatal("regional authority did not acquire a mutable lease")
	}
	controllerPublic, controllerPrivate := testEd25519(t, root, "controller.key")
	artifacts, err := broker.JetStream().CreateObjectStore(ctx, jetstream.ObjectStoreConfig{
		Bucket: "STATIC_ENROLLMENT_ARTIFACTS", Storage: jetstream.FileStorage, Replicas: 1})
	if err != nil {
		t.Fatal(err)
	}
	hostController, err := host.NewController(ctx, host.ControllerConfig{
		Cell: "gru", Conn: broker.Conn(), JS: broker.JetStream(), Artifacts: artifacts,
		StateReplicas: 1, ResponseKey: controllerPrivate, HostMutations: control,
		AuthorityEpoch: func() uint64 { return control.Current().Epoch }, AuthorityGuard: control.Guard,
	})
	if err != nil {
		t.Fatal(err)
	}
	go func() { _ = hostController.Run(ctx) }()
	select {
	case <-hostController.Ready():
	case <-ctx.Done():
		t.Fatal(ctx.Err())
	}
	grants, err := hostenroll.OpenGrantStore(ctx, broker.JetStream(), 1)
	if err != nil {
		t.Fatal(err)
	}
	bundle, issuer, _ := testHostEnrollmentTLSMaterial(t, controllerPublic)
	fleet := &staticHostFleet{instances: map[string]oci.CloudInstance{}}
	cfg := Config{NATS: natscell.Config{Cell: "gru"},
		Controller: ControllerConfig{Workloads: workloads, SpecTrust: newTestSpecTrust(t, root, cellspec.Identity{
			DeploymentID: "01ARZ3NDEKTSV4RRFFQ69G5FAV", Cell: "gru", Environment: "production"}).config()}}
	newAcceptedSpecTrust(t, &cfg)
	services, err := newSpecRegistry(cfg, "")
	if err != nil {
		t.Fatal(err)
	}
	return staticEnrollmentLab{enrollment: &managedHostEnrollment{cell: "gru", region: oci.RegionGRU,
		owner: "regional-owner", generation: 1, environment: "production", fleet: fleet,
		controller: hostController, grants: grants, issuer: issuer, responseKey: controllerPrivate,
		fencer: control, services: services},
		controller: hostController, fleet: fleet, bundle: bundle, epoch: control.Current().Epoch, js: broker.JetStream()}
}

func (lab staticEnrollmentLab) setup(ctx context.Context, root string, metadata hostenroll.InstanceMetadata, peerIP string) error {
	return runHostSetupWithMetadata(ctx, lab.bundle, metadata, root, &bytes.Buffer{}, hostSetupRuntime{
		ownerUID: uint32(os.Geteuid()), post: func(_ context.Context, _ hostenroll.PublicBundle, wire []byte) ([]byte, error) {
			return lab.post(wire, peerIP)
		}})
}

func (lab staticEnrollmentLab) post(wire []byte, peerIP string) ([]byte, error) {
	request := httptest.NewRequest(http.MethodPost, "https://10.251.0.11:8443/v1/host-enrollment", bytes.NewReader(wire))
	request.RemoteAddr = peerIP + ":44321"
	reply := httptest.NewRecorder()
	lab.enrollment.ServeHTTP(reply, request)
	if reply.Code != http.StatusOK {
		return nil, &hostEnrollmentHTTPStatusError{Code: reply.Code}
	}
	return reply.Body.Bytes(), nil
}

func (lab staticEnrollmentLab) registration(t *testing.T, ctx context.Context, node string) host.Registration {
	t.Helper()
	statuses, err := lab.controller.ListHosts(ctx)
	if err != nil {
		t.Fatal(err)
	}
	for _, status := range statuses {
		if status.Registration.Node == node {
			return status.Registration
		}
	}
	t.Fatalf("%s is not registered", node)
	return host.Registration{}
}

func (enrollment *managedHostEnrollment) enrollStatic(ctx context.Context, epoch uint64, peerIP string, wire []byte,
	request hostenroll.Request, descriptor hostboot.Descriptor,
) ([]byte, error) {
	if err := enrollment.fencer.Guard(ctx, epoch); err != nil {
		return nil, err
	}
	if descriptor.Cell != enrollment.cell || descriptor.Region != string(enrollment.region) {
		return nil, errors.New("static host descriptor is outside this regional cell")
	}
	csr, err := hostenroll.ParseCSR(request.CSRPEM)
	if err != nil {
		return nil, err
	}
	instance, admission, err := enrollment.observeStatic(ctx, peerIP, request, descriptor)
	if err != nil {
		return nil, err
	}

func (enrollment *managedHostEnrollment) observeStatic(ctx context.Context, peerIP string,
	request hostenroll.Request, descriptor hostboot.Descriptor,
) (oci.CloudInstance, staticAdmission, error) {
	if err := refuseUnprovenPoolDescriptor(descriptor); err != nil {
		return oci.CloudInstance{}, staticAdmission{}, err
	}
	peer, capacity, listed := enrollment.staticMember(descriptor.Node)
	_, _, granted := enrollment.services.hostGrant(descriptor.Node)
	if !granted && !listed && enrollment.pool != nil {
		return enrollment.observePoolNode(ctx, peerIP, request, descriptor)
	}
	if granted || !listed {
		return enrollment.observeGranted(ctx, peerIP, request, descriptor)
	}
	if peer.Address.Addr().String() != peerIP {
		return oci.CloudInstance{}, staticAdmission{}, errors.New("static host is not a listed TerraBase member at its private address")
	}
	observer, ok := enrollment.fleet.(oci.StaticHostObserver)
	if !ok {
		return oci.CloudInstance{}, staticAdmission{}, errors.New("regional fleet cannot observe static hosts")
	}
	instance, err := observer.ObserveStaticHost(ctx, request.InstanceID, descriptor.Node)
	if err != nil {
		return oci.CloudInstance{}, staticAdmission{}, err
	}
	if instance.PrivateIP != peerIP || instance.Metadata[hostboot.MetadataKey] != request.Descriptor {
		return oci.CloudInstance{}, staticAdmission{}, errors.New("direct peer does not match the static OCI host")
	}
	return instance, staticAdmission{Capacity: capacity}, nil
}

// observeGranted authenticates a host the adopted cell spec grants: the
// direct peer holds the grant's address, and OCI shows the running instance
// of the descriptor's name holding it.
func (enrollment *managedHostEnrollment) observeGranted(ctx context.Context, peerIP string,
	request hostenroll.Request, descriptor hostboot.Descriptor,
) (oci.CloudInstance, staticAdmission, error) {
	grant, capacity, ok := enrollment.services.hostGrant(descriptor.Node)
	if !ok || grant.PrivateIP != peerIP {
		return oci.CloudInstance{}, staticAdmission{}, errors.New("static host is neither a listed TerraBase member nor granted its private address")
	}
	observer, ok := enrollment.fleet.(oci.NamedHostObserver)
	if !ok {
		return oci.CloudInstance{}, staticAdmission{}, errors.New("regional fleet cannot observe granted hosts")
	}
	instance, err := observer.ObserveNamedHost(ctx, request.InstanceID, descriptor.Node)
	if err != nil {
		return oci.CloudInstance{}, staticAdmission{}, err
	}
	if instance.PrivateIP != peerIP {
		return oci.CloudInstance{}, staticAdmission{}, errors.New("direct peer does not match the granted instance")
	}
	return instance, staticAdmission{Grant: &grant, Capacity: capacity}, nil
}

// observePoolNode holds admission until protected original creation authority
// links this exact child instance to its budgeted pool operation.
func (enrollment *managedHostEnrollment) observePoolNode(context.Context, string,
	hostenroll.Request, hostboot.Descriptor,
) (oci.CloudInstance, staticAdmission, error) {
	return oci.CloudInstance{}, staticAdmission{}, oci.ErrPoolCreationLineagePending
}

// poolRoles are the roles a pool node runs: every reconciled service's role
// except the TerraBase member's.
func (enrollment *managedHostEnrollment) poolRoles() []string {
	_, specs := enrollment.services.effective()
	var roles []string
	for _, spec := range specs {
		if spec.Role != terrabase.Role {
			roles = append(roles, spec.Role)
		}
	}
	slices.Sort(roles)
	return slices.Compact(roles)
}

func refuseUnprovenPoolDescriptor(descriptor hostboot.Descriptor) error {
	cell, err := naming.RegionCell(descriptor.Region).Name()
	if err != nil {
		return err
	}
	if descriptor.IsStatic() && strings.HasPrefix(descriptor.Node, cell+"-pool-") {
		return oci.ErrPoolCreationLineagePending
	}
	return nil
}

func (enrollment *managedHostEnrollment) ServeHTTP(writer http.ResponseWriter, request *http.Request) {
	if request.URL.Path == "/v1/runtime/worker-refresh" {
		enrollment.refreshRuntimeWorker(writer, request)
		return
	}
	if request.URL.Path == "/v1/runtime/worker-bind" {
		enrollment.bindRuntimeWorker(writer, request)
		return
	}
	if request.Method != http.MethodPost || request.URL.Path != "/v1/host-enrollment" || request.TLS == nil ||
		request.Header.Get("Forwarded") != "" || request.Header.Get("X-Forwarded-For") != "" ||
		request.Header.Get("X-Real-IP") != "" {
		http.Error(writer, "invalid host enrollment request", http.StatusBadRequest)
		return
	}
	snapshot := enrollment.fencer.Current()
	if !snapshot.CanMutate() {
		http.Error(writer, "regional authority is not writable", http.StatusServiceUnavailable)
		return
	}
	peerIP, _, err := net.SplitHostPort(request.RemoteAddr)
	if err != nil || net.ParseIP(peerIP) == nil {
		http.Error(writer, "direct private peer is required", http.StatusForbidden)
		return
	}
	wire, err := io.ReadAll(io.LimitReader(request.Body, hostenroll.MaxRequestBytes+1))
	if err != nil || len(wire) > hostenroll.MaxRequestBytes {
		http.Error(writer, "host enrollment request is too large", http.StatusRequestEntityTooLarge)
		return
	}
	enrollmentRequest, descriptor, err := hostenroll.ParseRequest(wire, time.Now().UTC())
	if err != nil {
		var historical hostenroll.Request
		if json.Unmarshal(wire, &historical, json.RejectUnknownMembers(true)) != nil ||
			historical.IssuedAt.IsZero() || !historical.IssuedAt.Before(time.Now().Add(-48*time.Hour)) {
			http.Error(writer, "host enrollment request is invalid", http.StatusBadRequest)
			return
		}
		enrollmentRequest, descriptor, err = hostenroll.ParseRequest(wire, historical.IssuedAt.Add(time.Second))
		if err != nil {
			http.Error(writer, "host enrollment request is invalid", http.StatusBadRequest)
			return
		}
		grant, _, readErr := enrollment.grants.Read(request.Context(), enrollmentRequest.InstanceID)
		stored := grant.Request
		if enrollmentRequest.Operation == "renew" {
			stored = grant.RenewalRequest
		}
		if readErr != nil || grant.Disabled || !bytes.Equal(wire, stored) {
			http.Error(writer, "stale host request has no exact grant", http.StatusPreconditionFailed)
			return
		}
	}
	response, err := enrollment.enroll(request.Context(), snapshot.Epoch, peerIP, wire, enrollmentRequest, descriptor)
	if err != nil {
		if errors.Is(err, errStaleUnclaimedRenewal) {
			writer.Header().Set("X-TerraScale-Host-Enrollment-Error", staleUnclaimedRenewal)
			http.Error(writer, "stale unclaimed host renewal", http.StatusPreconditionFailed)
			return
		}
		http.Error(writer, "host enrollment held", http.StatusConflict)
		return
	}
	writer.Header().Set("Content-Type", "application/json")
	writer.Header().Set("Cache-Control", "no-store")
	_, _ = writer.Write(response)
}

func (enrollment *managedHostEnrollment) enroll(ctx context.Context, epoch uint64, peerIP string, wire []byte,
	request hostenroll.Request, descriptor hostboot.Descriptor,
) ([]byte, error) {
	if descriptor.IsStatic() {
		return enrollment.enrollStatic(ctx, epoch, peerIP, wire, request, descriptor)
	}
	ctx = authority.WithActiveWorkloadEffectContext(ctx)
	release, err := enrollment.beginActiveEffect(ctx, epoch, descriptor)
	if err != nil {
		return nil, err
	}
	defer release()
	return enrollment.enrollActive(ctx, epoch, peerIP, wire, request, descriptor)
}

func runHostSetupWithMetadata(ctx context.Context, bundle hostenroll.PublicBundle,
	metadata hostenroll.InstanceMetadata, outputRoot string, output io.Writer, runtime hostSetupRuntime,
) error {
	if runtime.post == nil {
		return errors.New("host enrollment transport is unavailable")
	}
	if err := bundle.Validate(); err != nil {
		return err
	}
	currentDescriptor, err := hostboot.ParseHost(metadata.Wire)
	if err != nil || currentDescriptor != metadata.Descriptor || !validEnrollmentInstanceID(metadata.InstanceID) {
		return errors.New("current OCI host metadata is invalid")
	}
	if metadata.Descriptor.Cell != bundle.Cell || metadata.Descriptor.Region != bundle.Region {
		return errors.New("OCI host descriptor differs from image-pinned regional bundle")
	}
	if err := validateHostSetupRootOwner(outputRoot, runtime.ownerUID); err != nil {
		return err
	}
	secrets := outputRoot
	if runtime.secrets != "" {
		secrets = runtime.secrets
		if err := validateHostSetupRootOwner(secrets, runtime.ownerUID); err != nil {
			return err
		}
	}
	if runtime.identity != nil {
		if err := runtime.identity.restore(ctx, outputRoot, secrets); err != nil {
			return err
		}
	}
	renamed, err := resetRenamedHostEnrollment(outputRoot, secrets, metadata)
	if err != nil {
		return err
	}
	pending, err := readOrCreateHostEnrollment(ctx, secrets, metadata, runtime.identity)
	if err != nil {
		return err
	}
	var original hostenroll.Request
	if err := json.Unmarshal(pending.Request, &original, json.RejectUnknownMembers(true)); err != nil {
		return err
	}
	request, descriptor, err := hostenroll.ParseRequest(pending.Request, original.IssuedAt.Add(time.Second))
	if err != nil || request.InstanceID != metadata.InstanceID || request.Descriptor != string(metadata.Wire) ||
		descriptor != metadata.Descriptor || request.Operation != "enroll" {
		return errors.New("persisted host enrollment request differs from current OCI metadata")
	}
	// A renamed host's installed configuration names its old node.
	active := false
	if !renamed && runtime.identity != nil {
		if err := recoverHostCredentials(ctx, outputRoot, secrets, bundle, descriptor, pending, request, runtime); err != nil {
			return err
		}
	}
	if !renamed {
		if active, err = installedHostCredentialActive(outputRoot, secrets, bundle, descriptor.Node, pending, request); err != nil {
			return err
		}
	}
	if active && descriptor.IsController() {
		if _, err := os.Stat(filepath.Join(outputRoot, runtimeWorkerTransportFilename)); errors.Is(err, os.ErrNotExist) {
			active = false
		} else if err != nil {
			return err
		}
	}
	if active {
		_, _ = fmt.Fprintf(output, "host %s enrollment is current in cell %s\n", descriptor.Node, bundle.Cell)
		return cleanLegacyHostEnrollment(runtime, outputRoot, secrets)
	}
	requestWire := pending.Request
	if _, err := os.Stat(filepath.Join(outputRoot, "host.json")); err == nil && !renamed {
		requestWire, err = createRenewalRequest(outputRoot, pending, request)
		if err != nil {
			return err
		}
	}
	request, err = parsePersistedHostRequest(requestWire)
	if err != nil {
		return err
	}
	responseWire, err := runtime.post(ctx, bundle, requestWire)
	if status, ok := errors.AsType[*hostEnrollmentHTTPStatusError](err); ok &&
		status.Code == http.StatusPreconditionFailed && time.Since(request.IssuedAt) > 48*time.Hour {
		if request.Operation == "renew" {
			requestWire, err = createFreshRenewalRequest(outputRoot, pending, original)
		} else {
			requestWire, err = createFreshInitialRequest(ctx, secrets, pending, original, runtime.identity)
		}
		if err != nil {
			return err
		}
		request, err = parsePersistedHostRequest(requestWire)
		if err != nil {
			return err
		}
		responseWire, err = runtime.post(ctx, bundle, requestWire)
	}
	if status, ok := errors.AsType[*hostEnrollmentHTTPStatusError](err); ok &&
		status.Code == http.StatusPreconditionFailed && status.Kind == staleUnclaimedRenewal &&
		request.Operation == "renew" && time.Since(request.IssuedAt) > 5*time.Minute {
		requestWire, err = createFreshRenewalRequest(outputRoot, pending, original)
		if err != nil {
			return err
		}
		request, err = parsePersistedHostRequest(requestWire)
		if err != nil {
			return err
		}
		responseWire, err = runtime.post(ctx, bundle, requestWire)
	}
	if err != nil {
		return err
	}

